// UI strings. t(key, params) with {name} placeholders. RU is the primary language and the fallback.
// UK, UZ and TT are full translations; a missing key falls back to RU.
let lang = 'ru';
export const LANGS = [['ru', 'Русский'], ['en', 'English'], ['uk', 'Українська'], ['uz', 'Oʻzbekcha'], ['tt', 'Татарча']];
export const setLang = (l) => { lang = LANGS.some(([c]) => c === l) ? l : 'ru'; };
export const currentLang = () => lang;

export function t(key, params) {
  const dict = { en: EN, uk: UK, uz: UZ, tt: TT }[lang] || RU;
  let s = dict[key];
  if (s === undefined) s = RU[key];
  if (s === undefined) return key;
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] !== undefined ? String(params[k]) : m));
  return s;
}

